import os
import requests

def extract_receipt_fields(payload, config=None):
    config = config or {}
    api_key = config.get("MINDEE_API_KEY") or os.environ.get("MINDEE_API_KEY")
    headers = {"Authorization": f"Token {api_key}"}
    files = {"document": ("receipt.jpg", payload, "application/octet-stream")}
    response = requests.post("https://api.mindee.net/v1/products/mindee/receipts/v5/predict", headers=headers, files=files)
    pred = response.json()["document"]["inference"]["prediction"]
    result = {
        "merchant": pred.get("supplier", {}).get("value"),
        "tax": sum(t.get("value", 0) for t in pred.get("taxes", [])),
        "total": pred.get("total_amount", {}).get("value"),
        "items": [{"description": i.get("description", ""), "quantity": i.get("quantity", 0), "price": i.get("total_price", 0)} for i in pred.get("line_items", [])]
    }
    return result
